import React, { useState, useEffect } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { adminService } from '../../services/adminService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage, getStatusText, getStatusColor, formatDateTime } from '../../utils/helpers';
import { APPLICATION_STATUS } from '../../utils/constants';

const ApplicationManagement = () => {
  const [applications, setApplications] = useState([]);
  const [filteredApplications, setFilteredApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchParams, setSearchParams] = useSearchParams();
  const [filters, setFilters] = useState({
    status: searchParams.get('status') || '',
    search: ''
  });

  useEffect(() => {
    loadApplications();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [applications, filters]);

  useEffect(() => {
    // Update URL when filters change
    const params = new URLSearchParams();
    if (filters.status) params.set('status', filters.status);
    if (filters.search) params.set('search', filters.search);
    setSearchParams(params);
  }, [filters, setSearchParams]);

  const loadApplications = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await adminService.getAllApplications();
      setApplications(response.data);
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...applications];

    // Filter by status
    if (filters.status) {
      filtered = filtered.filter(app => app.status === filters.status);
    }

    // Filter by search term
    if (filters.search) {
      const searchTerm = filters.search.toLowerCase();
      filtered = filtered.filter(app =>
        (app.vendor?.name && app.vendor.name.toLowerCase().includes(searchTerm)) ||
        (app.vendor?.user?.username && app.vendor.user.username.toLowerCase().includes(searchTerm)) ||
        (app.vendor?.user?.email && app.vendor.user.email.toLowerCase().includes(searchTerm)) ||
        (app.id.toString().includes(searchTerm))
      );
    }

    setFilteredApplications(filtered);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  };

  const clearFilters = () => {
    setFilters({
      status: '',
      search: ''
    });
  };

  const getStatusCount = (status) => {
    return applications.filter(app => app.status === status).length;
  };

  if (loading) {
    return <LoadingSpinner message="Loading applications..." />;
  }

  return (
    <div className="application-management-page">
      <div className="container">
        <div className="page-header">
          <h1>Application Management</h1>
          <p>Review and manage all license applications</p>
        </div>

        {error ? (
          <div className="error-container">
            <div className="error-message">
              <p>{error}</p>
              <button onClick={loadApplications} className="btn btn-primary">
                Try Again
              </button>
            </div>
          </div>
        ) : (
          <>
            {/* Status Summary Cards */}
            <div className="status-summary">
              <div className="summary-cards">
                <div className="summary-card">
                  <h4>Submitted</h4>
                  <span className="count">{getStatusCount('SUBMITTED')}</span>
                </div>
                <div className="summary-card">
                  <h4>Under Review</h4>
                  <span className="count">{getStatusCount('UNDER_REVIEW')}</span>
                </div>
                <div className="summary-card">
                  <h4>Approved</h4>
                  <span className="count">{getStatusCount('APPROVED')}</span>
                </div>
                <div className="summary-card">
                  <h4>Rejected</h4>
                  <span className="count">{getStatusCount('REJECTED')}</span>
                </div>
              </div>
            </div>

            {/* Filters */}
            <div className="filters-section">
              <div className="filters-row">
                <div className="filter-group">
                  <label htmlFor="search">Search</label>
                  <input
                    type="text"
                    id="search"
                    placeholder="Search by application ID, vendor name, or username..."
                    value={filters.search}
                    onChange={(e) => handleFilterChange('search', e.target.value)}
                  />
                </div>

                <div className="filter-group">
                  <label htmlFor="status">Status</label>
                  <select
                    id="status"
                    value={filters.status}
                    onChange={(e) => handleFilterChange('status', e.target.value)}
                  >
                    <option value="">All Statuses</option>
                    {Object.entries(APPLICATION_STATUS).map(([key, value]) => (
                      <option key={key} value={value}>
                        {getStatusText(value)}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="filter-actions">
                  <button onClick={clearFilters} className="btn btn-outline">
                    Clear Filters
                  </button>
                </div>
              </div>
            </div>

            {/* Results Summary */}
            <div className="results-summary">
              <p>
                Showing {filteredApplications.length} of {applications.length} applications
              </p>
            </div>

            {/* Applications Table */}
            {filteredApplications.length > 0 ? (
              <div className="applications-table-container">
                <table className="applications-table">
                  <thead>
                    <tr>
                      <th>Application ID</th>
                      <th>Vendor</th>
                      <th>Business Name</th>
                      <th>Status</th>
                      <th>Submitted</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredApplications.map((application) => (
                      <tr key={application.id}>
                        <td>
                          <strong>#{application.id}</strong>
                        </td>
                        <td>
                          <div className="vendor-info">
                            <div>{application.vendor?.user?.username || 'N/A'}</div>
                            <small>{application.vendor?.user?.email || 'N/A'}</small>
                          </div>
                        </td>
                        <td>
                          <div className="business-info">
                            <strong>{application.vendor?.name || 'N/A'}</strong>
                            <small>{application.vendor?.operatingRegion || 'N/A'}</small>
                          </div>
                        </td>
                        <td>
                          <span className={`status-badge ${getStatusColor(application.status)}`}>
                            {getStatusText(application.status)}
                          </span>
                        </td>
                        <td>
                          {application.submittedAt ? 
                            formatDateTime(application.submittedAt) : 
                            'Not submitted'
                          }
                        </td>
                        <td>
                          <Link 
                            to={`/admin/application/${application.id}`} 
                            className="btn btn-sm btn-primary"
                          >
                            View Details
                          </Link>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="no-results">
                <h3>No applications found</h3>
                <p>Try adjusting your filters or search terms.</p>
                <button onClick={clearFilters} className="btn btn-primary">
                  Clear All Filters
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default ApplicationManagement;
